<section class="page-heading small-heading"><div class="site-width"><a class="breadcrumb" href="<?= e(url('admin/lessons')) ?>">← Tagasi õppematerjalide juurde</a><span class="section-label">TESTI HALDUS</span><h1><?= e($lesson['title']) ?></h1><p>Lisa õppematerjalile valikvastustega küsimused. Vali üks õige vastus.</p></div></section><section class="site-width form-page"><div class="dashboard-panel admin-form-panel"><h2>Lisa uus küsimus</h2><?php if ($notice=flash()): ?><div class="alert alert-success" role="status"><?= e($notice) ?></div><?php endif; ?><?php if ($formError): ?><div class="alert alert-error" role="alert"><?= e($formError) ?></div><?php endif; ?><form method="post" action="<?= e(url('admin/quiz')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="lesson_id" value="<?= (int)$lesson['id'] ?>"><label for="question">Küsimus</label><input class="form-control" id="question" name="question" maxlength="500" minlength="5" required value="<?= e($_POST['question']??'') ?>"><div class="answer-settings"><?php for($i=0;$i<3;$i++): ?><label for="option-<?= $i ?>">Vastusevariant <?= $i+1 ?></label><div class="answer-setting-row"><input type="radio" name="correct" value="<?= $i ?>" aria-label="Variant <?= $i+1 ?> on õige" <?= (string)($_POST['correct']??'0')===(string)$i?'checked':'' ?>><input class="form-control" id="option-<?= $i ?>" name="options[]" maxlength="300" required value="<?= e($_POST['options'][$i]??'') ?>"></div><?php endfor; ?></div><p class="muted">Märgi õige vastuse kõrval olev ring.</p><button class="btn btn-primary" type="submit">+ Lisa küsimus</button></form></div><div class="dashboard-panel"><h2>Olemasolevad küsimused (<?= count($questions) ?>)</h2><?php if (!$questions): ?><p>Siin pole veel küsimusi. Lisa esimene küsimus ülal oleva vormiga.</p><?php endif; ?><?php foreach ($questions as $i=>$question): ?><div class="admin-question"><h3><?= $i+1 ?>. <?= e($question['question']) ?></h3><ol><?php foreach ($question['options'] as $option): ?><li><?= e($option['option_text']) ?></li><?php endforeach; ?></ol><form method="post" action="<?= e(url('admin/quiz')) ?>" onsubmit="return confirm('Kas kustutada see küsimus?');"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="lesson_id" value="<?= (int)$lesson['id'] ?>"><input type="hidden" name="question_id" value="<?= (int)$question['id'] ?>"><input type="hidden" name="action" value="delete"><button class="delete-link" type="submit">Kustuta küsimus</button></form></div><?php endforeach; ?></div></section>
